+       tView,
+       lView,
+       hostIndex,
+       eventName,
+       eventName,
+       listenerFn,
+       lCleanup,
+       tCleanup,
+     );
+   }
+ 
+   return hasOutput;
+ }
+ 
+ export function listenToOutput(
+   tNode: TNode,
+   tView: TView,
+   lView: LView,
+   index: number,
+   lookupName: string,
+   eventName: string,
+   listenerFn: (e?: any) => any,
+   lCleanup: any[],
+   tCleanup: any[] | null,
+ ) {
+   ngDevMode && assertIndexInRange(lView, index);
