+    * @param injector
+    * @param addSpacer Enabled by default. Use when the position of the animation is `fixed`.
+    */
+   constructor(
+     private hostElementRef: ElementRef,
+     injector: Injector,
+     private addSpacer: boolean = true,
+   ) {
