+     this.unlisteners.push(
+       this.renderer.listen(this.win, 'scroll', () => {
+         if (animation.isPlaying()) {
+           animation.pause();
+         }
+         const progress = this.win.scrollY / this.scrollHeight;
+         animation.seek(progress);
+       }),
+     );
