+   for (let i = 0; i < text.length; i++) {
+     const char = text[i];
+ 
+     if (TERMINAL_CHAR.includes(char)) {
+       attemptToPushToken(i);
+       tokens.push({
+         type: CHAR_TO_TOKEN[char],
+         value: char,
+         idx: i,
+       });
+     } else {
